using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Infrastructure;using Microsoft.Extensions.DependencyInjection;using Microsoft.Extensions.DependencyInjection.Extensions;using RaceDay.Api.Data;using RaceDay.Api.Models;using RaceDay.Api.Services;using System.Net.Http.Headers;using System.Net.Http.Json;
namespace RaceDay.Tests;
public class ApiFactory:WebApplicationFactory<Program>{
 protected override void ConfigureWebHost(IWebHostBuilder builder){builder.UseEnvironment("Development");builder.ConfigureServices(services=>{services.RemoveAll(typeof(DbContextOptions<RaceDayContext>));services.RemoveAll(typeof(IDbContextOptionsConfiguration<RaceDayContext>));services.RemoveAll(typeof(RaceDayContext));services.AddDbContext<RaceDayContext>(o=>o.UseInMemoryDatabase("RaceDayTests_"+Guid.NewGuid()));});}
 public async Task SeedAsync(){using var scope=Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<RaceDayContext>();await db.Database.EnsureDeletedAsync();await db.Database.EnsureCreatedAsync();var orgRole=new Role{RoleName="Organiser"};var parRole=new Role{RoleName="Participant"};db.Roles.AddRange(orgRole,parRole);await db.SaveChangesAsync();var ps=scope.ServiceProvider.GetRequiredService<IPasswordService>();var org=new User{FirstName="Olivia",LastName="Organiser",Email="organiser@raceday.test",RoleID=orgRole.RoleID,Role=orgRole};org.PasswordHash=ps.Hash(org,"Organiser123!");var par=new User{FirstName="Peter",LastName="Participant",Email="participant@raceday.test",RoleID=parRole.RoleID,Role=parRole};par.PasswordHash=ps.Hash(par,"Participant123!");db.Users.AddRange(org,par);await db.SaveChangesAsync();var ev=new RaceEvent{OrganiserID=org.UserID,EventName="Test Run",EventDate=DateTime.UtcNow.Date.AddDays(10),Location="Cape Town",Status="Open"};var cat=new Category{CreatedByUserID=org.UserID,CategoryName="5 km",DistanceKm=5};db.Events.Add(ev);db.Categories.Add(cat);await db.SaveChangesAsync();db.EventCategories.Add(new EventCategory{EventID=ev.EventID,CategoryID=cat.CategoryID,EntryFee=50,Capacity=20});await db.SaveChangesAsync();}
 public async Task<string> LoginAsync(string email,string password){var client=CreateClient();var res=await client.PostAsJsonAsync("/api/auth/login",new{email,password});res.EnsureSuccessStatusCode();var body=await res.Content.ReadFromJsonAsync<TokenPayload>();return body!.AccessToken;}
 public HttpClient AuthClient(string token){var c=CreateClient();c.DefaultRequestHeaders.Authorization=new AuthenticationHeaderValue("Bearer",token);return c;}
 private sealed record TokenPayload(string AccessToken);
}
